import {TalkingBustView} from './talking-bust.js';
import {CATALOG} from './catalog.js';import {RecordedNarrator,validateCues} from './recorded-narrator.js';import {parseVtt} from './timed-cues.js';
const $=id=>document.getElementById(id),lula=CATALOG.find(p=>p.id==='lula');let audioUrl=null,scriptUrl=null,cues=[],track=null;
$('pilot-script').value=lula.narration;$('pilot-source').href=lula.source;const c=lula.portraitCredit;$('pilot-credit').textContent=c.artist+' · '+c.license;const credit=document.createElement('a');credit.href=c.page;credit.textContent=' · Origem e licença ↗';credit.target='_blank';credit.rel='noopener noreferrer';$('pilot-credit').append(credit);
let avatar;
const guide=new RecordedNarrator({onChange:s=>{avatar?.setState(s.state);const messages={idle:'Áudio pronto para teste.',loading:'Carregando o áudio…',playing:s.synchronized?'Reproduzindo com legendas sincronizadas.':'Reproduzindo. Sem marcações de tempo, acompanhe o roteiro completo abaixo.',paused:'Reprodução pausada.',ended:'Narração concluída.',error:'Não foi possível reproduzir o arquivo. Confira o formato e tente outro áudio.'};$('pilot-status').textContent=audioUrl?messages[s.state]:'Aguardando o áudio. A voz do ElevenLabs ainda não foi gerada neste projeto.';$('pilot-caption').textContent=s.synchronized?(s.caption||'…'):'Sem legendas sincronizadas. Leia o roteiro completo abaixo.';$('pilot-play').disabled=!audioUrl||['playing','loading'].includes(s.state);$('pilot-play').textContent=s.state==='paused'?'▶ Continuar':'▶ Ouvir';$('pilot-pause').disabled=s.state!=='playing';for(const id of ['pilot-restart','pilot-stop'])$(id).disabled=!audioUrl;}});
function load(){if(audioUrl)guide.load(lula.narration,{src:audioUrl,cues});}
$('audio-file').onchange=()=>{guide.stop();if(audioUrl)URL.revokeObjectURL(audioUrl);audioUrl=null;const f=$('audio-file').files[0];if(!f)return;if(f.size>50*1024*1024){$('pilot-status').textContent='Escolha um áudio de até 50 MB para este teste.';return;}audioUrl=URL.createObjectURL(f);load();};
$('cue-file').onchange=async()=>{const file=$('cue-file').files[0];if(!file){cues=[];load();return;}try{if(file.size>2*1024*1024)throw Error('O arquivo de legendas deve ter até 2 MB.');const text=await file.text();const next=file.name.toLowerCase().endsWith('.vtt')?parseVtt(text):(JSON.parse(text).cues||JSON.parse(text));cues=validateCues(next);load();$('pilot-status').textContent=cues.length+' trechos de legenda carregados. Confira se correspondem ao áudio.';}catch(e){$('pilot-status').textContent=e.message;}};
$('pilot-play').onclick=()=>guide.play();$('pilot-pause').onclick=()=>guide.pause();$('pilot-restart').onclick=()=>guide.restart();$('pilot-stop').onclick=()=>guide.stop();$('copy-script').onclick=async()=>{try{await navigator.clipboard.writeText(lula.narration);$('copy-script').textContent='Roteiro copiado';}catch{$('pilot-script').select();$('copy-script').textContent='Selecione e copie o texto acima';}};
scriptUrl=URL.createObjectURL(new Blob([lula.narration],{type:'text/plain;charset=utf-8'}));$('download-script').href=scriptUrl;window.addEventListener('pagehide',()=>{guide.stop();if(audioUrl)URL.revokeObjectURL(audioUrl);if(scriptUrl)URL.revokeObjectURL(scriptUrl);});

fetch('assets/audio/manifest.json').then(r=>r.json()).then(m=>{if(audioUrl)return;const recording=m.recordings?.lula;if(recording){audioUrl=recording.src;cues=recording.cues||[];load();}}).catch(()=>{$('pilot-status').textContent='Não foi possível carregar a narração. Selecione um arquivo local para testar.';});

avatar=new TalkingBustView($('talking-lula'),{audio:()=>guide.audio});$('talking-mode').textContent=$('talking-lula').dataset.renderer==='webgl'?'Personagem 3D estilizado · piscar e movimento de cabeça · boca reage ao áudio.':'Seu navegador está exibindo a versão ilustrada animada. A versão 3D é usada quando WebGL está disponível.';window.addEventListener('pagehide',()=>avatar.destroy());
